    async def get_assets_with_their_tasks(
        self,
        *,
        project_id: Optional[str] = None,
        episode_id: Optional[str] = None,
        compact: Optional[bool] = None,
        stream: Optional[bool] = None,
        assigned_to: Optional[str] = None,
    ) -> list[GetAssetsWithTheirTasksItem]:
        """Get assets with their tasks.

        Get the assets of the projects that you can access, with the tasks of each
        asset. Each asset has its project name and asset type name. Filter with
        project_id, episode_id or assigned_to. The other columns are not filters on this
        route. A vendor gets only the assets of their assigned tasks, without the
        metadata columns hidden from their departments. A client gets the tasks without
        the studio fields (assignees, estimation, dates, retake count). The response can
        have an ETag. Send it in If-None-Match to get a 304 response when the data did
        not change.

        Args:
            project_id: Filter assets by specific project
            episode_id: Get the assets of this episode and the assets cast in this
                episode. Use main to get the assets that have no episode. Use all to get the
                assets of all episodes.
            compact: Encode assets and tasks as positional value arrays (halves the
                payload). Field names are given by the asset_fields and task_fields entries
                of the response, map values by name, never by hardcoded position.
            stream: Stream the response as NDJSON (one header line, then one asset per
                line) instead of a single JSON document, to keep server memory flat on large
                productions.
            assigned_to: With any value, get only the assets that have a task assigned
                to you.

        ``GET /data/assets/with-tasks``
        """
        return await self._t.request(
            "GET",
            "/data/assets/with-tasks",
            params={
                "project_id": project_id,
                "episode_id": episode_id,
                "compact": compact,
                "stream": stream,
                "assigned_to": assigned_to,
            },
            response_type=list[GetAssetsWithTheirTasksItem],
        )

